package com.fitmind.service;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import com.fitmind.dto.WeightRecordRequest; import com.fitmind.entity.WeightRecord; import com.fitmind.exception.BusinessException; import com.fitmind.mapper.WeightRecordMapper; import org.junit.jupiter.api.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class WeightServiceTest { WeightRecordMapper mapper; WeightService service; @BeforeEach void setUp(){mapper=mock(WeightRecordMapper.class);service=new WeightService(mapper);} @Test void create(){when(mapper.selectOne(any())).thenReturn(null);when(mapper.insert(any())).thenAnswer(i->{i.<WeightRecord>getArgument(0).setId(19L);return 1;});assertEquals(19L,service.create(req("2026-08-13","56.7")).getId());} @Test void duplicate(){when(mapper.selectOne(any())).thenReturn(record(1));assertEquals(409,assertThrows(BusinessException.class,()->service.create(req("2026-08-12","56.8"))).getCode());} @Test void updateMissing(){when(mapper.selectById(99L)).thenReturn(null);assertEquals(404,assertThrows(BusinessException.class,()->service.update(99,req("2026-08-13","56"))).getCode());} @Test void deleteMissing(){when(mapper.selectById(99L)).thenReturn(null);assertThrows(BusinessException.class,()->service.delete(99));} @Test void pageOrder(){Page<WeightRecord> p=new Page<>(1,5);p.setRecords(Arrays.asList(record(2),record(1)));p.setTotal(2);when(mapper.selectPage(any(),any())).thenReturn(p);assertEquals(2,service.page(1,5).getRecords().get(0).getId());} static WeightRecordRequest req(String d,String w){WeightRecordRequest r=new WeightRecordRequest();r.setRecordDate(LocalDate.parse(d));r.setWeightKg(new BigDecimal(w));return r;} static WeightRecord record(long id){WeightRecord r=new WeightRecord();r.setId(id);r.setUserId(1L);r.setRecordDate(LocalDate.of(2026,8,(int)Math.min(12,id)));r.setWeightKg(new BigDecimal("56.80"));return r;} }
